def check(c: str) -> int:
    """返回字符类别：1-alpha(小写) 2-beta(大写) 3-gamma(数字) 0-omega(其他)"""
    if c.islower():
        return 1
    if c.isupper():
        return 2
    if c.isdigit():
        return 3
    return 0

def solve(n: int, A: str, B: str) -> str:
    result = []
    for i in range(n):
        ca = check(A[i])
        cb = check(B[i])
        if ca > 0 and cb > 0:          # 两者都不是 omega
            a = ord(A[i])
            b = ord(B[i])
            if a > b:
                a, b = b, a
            mid = (a + b + 1) // 2   # 向上取整的中位码值
            if ca == cb:
                result.append(chr(mid))
            else:
                result.append(str(mid))
        else:
            result.append('_')
    return ''.join(result)

if __name__ == "__main__":
    n = int(input())
    A = input()
    B = input()
    print(solve(n, A, B))
```

